/** Persisted order record. */
export interface Order {
  id: string;
  total: number;
}

/** Prefix of the error raised when a requested identifier has no persisted order. */
const ORDER_NOT_FOUND_MESSAGE = "order not found";

/** Data access contract used by {@link loadOrders}. */
export interface OrderStore {
  /**
   * Resolves every requested order in a single query.
   *
   * @param ids - Order identifiers to resolve; duplicates may be present.
   * @returns The orders that exist, in unspecified order; identifiers without an order are omitted.
   * @remarks Implementations must issue exactly one query per call.
   */
  findByIds(ids: readonly string[]): Promise<Order[]>;
}

/**
 * Loads orders by identifier while preserving the requested order.
 *
 * @param store - Order data store.
 * @param ids - Order identifiers in the desired output order; duplicates resolve to the same order.
 * @returns The resolved orders, positionally aligned with `ids`.
 * @throws Error when an identifier does not resolve; the first missing identifier in `ids` is reported.
 * @remarks Issues one store query per call and none when `ids` is empty.
 */
export async function loadOrders(store: OrderStore, ids: string[]): Promise<Order[]> {
  if (ids.length === 0) {
    return [];
