  const orders: Order[] = [];
  for (const id of ids) {
    const order = ordersById.get(id);
    if (order === undefined) {
      throw new Error(`${ORDER_NOT_FOUND_MESSAGE}: ${id}`);
    }
    orders.push(order);
  }
